CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER COLLATE NOCASE, c1  CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT, c3 BLOB NOT NULL DEFAULT 0, c4 VARCHAR(10));
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(1e-7, '日本', 'epsilon', 773, NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT, c1  COLLATE NOCASE, c2 VARCHAR(10) CHECK(c2 IS NULL OR length(c2) < 40), c3 NUMERIC CHECK(c3 IS NULL OR length(c3) < 40), c4 NUMERIC);
SELECT date('bad'), time('bad'), datetime('bad', '+12 hours'), julianday('bad'), strftime('%j %w %W', 'bad'), unixepoch('bad'), timediff('2024-03-01', '2023-01-15');
SELECT date('2038-01-19 03:14:07'), time('2038-01-19 03:14:07'), datetime('2038-01-19 03:14:07', '+1 day'), julianday('2038-01-19 03:14:07'), strftime('%J', '2038-01-19 03:14:07'), unixepoch('2038-01-19 03:14:07'), timediff('2024-03-01', '2023-01-15');
SELECT date('1999-12-31T23:59:59.999'), time('1999-12-31T23:59:59.999'), datetime('1999-12-31T23:59:59.999', '+1 day'), julianday('1999-12-31T23:59:59.999'), strftime('%j %w %W', '1999-12-31T23:59:59.999'), unixepoch('1999-12-31T23:59:59.999'), timediff('2024-03-01', '2023-01-15');
SELECT date(2451545.0), time(2451545.0), datetime(2451545.0, '+1 year'), julianday(2451545.0), strftime('%s', 2451545.0), unixepoch(2451545.0), timediff('2024-03-01', '2023-01-15');
SELECT id, id, ntile(3) OVER (PARTITION BY id IS NULL ORDER BY id) FROM t1 ORDER BY id;
